import { EllipsisVertical } from 'lucide-react'
import { Fragment } from 'react'
import { Button } from '@/registry/new-york/ui/button/components/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger
} from '@/registry/new-york/ui/dropdown-menu/components/dropdown-menu'

// Component
export const DataTableActionCell = ({
  menus,
  isLoading
}: {
  menus: Array<{
    id: string
    icon?: React.ReactNode
    label?: React.ReactNode
    slot?: React.ReactNode
    link?: string
    onClick?: () => void
  }>
  isLoading?: boolean
}) => {
  // Template
  if (menus.length === 0) {
    return null
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button isLoading={isLoading} size='icon' variant='ghost'>
          <EllipsisVertical className='size-4' />
        </Button>
      </DropdownMenuTrigger>

      <DropdownMenuContent>
        {menus.map((menu) => {
          if (menu.slot) {
            return <Fragment key={menu.id}>{menu.slot}</Fragment>
          }

          if (menu.link) {
            return (
              <DropdownMenuItem asChild key={menu.id}>
                <a href={menu.link}>
                  {menu.icon}
                  {menu.label}
                </a>
              </DropdownMenuItem>
            )
          }

          return (
            <DropdownMenuItem key={menu.id} onClick={menu.onClick}>
              {menu.icon}
              {menu.label}
            </DropdownMenuItem>
          )
        })}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

import type { RowData } from '@tanstack/react-table'
import type { DataTableProps } from './data-table'

// Component
const DataTableAdditionalInfo = <TData extends RowData>({
  table,
  isLoading,
  isError
}: Pick<DataTableProps<TData>, 'table' | 'isError' | 'isLoading'>) => {
  const rowLength = table.getRowModel().rows.length
  const isEmpty = !(rowLength || isLoading)

  // Template
  if (isError) {
    return <div className='flex items-center justify-center p-4'>An error occurred, please reload the page</div>
  }

  if (isEmpty) {
    return <div className='flex items-center justify-center p-4'>No data available</div>
  }

  return null
}

export default DataTableAdditionalInfo

import { flexRender, type RowData } from '@tanstack/react-table'
import React from 'react'
import { TableBody, TableCell, TableRow } from '@/registry/new-york/ui/table/components/table'
import { cn } from '@/utils/ui'
import type { DataTableProps } from './data-table'
import { getCommonPinningStyles } from './lib'

const DataTableBody = <TData extends RowData>({
  table,
  className,
  onRenderSubComponent,
  onRenderAdditionalRow
}: Pick<DataTableProps<TData>, 'table' | 'onRenderSubComponent' | 'onRenderAdditionalRow'> & {
  className?: string
}) => {
  const rows = table.getRowModel().rows

  // Template
  return (
    <TableBody className={cn('relative', className)}>
      {rows.map((row) => {
        const isExpanded = row.getIsExpanded()
        const rowClassName: string =
          (typeof row.original === 'object' && row.original && 'className' in row.original
            ? (row.original.className as string)
            : '') ?? ''

        return (
          <React.Fragment key={row.id}>
            <TableRow
              className={cn('[&:not(:last-child)_td]:border-b', isExpanded && 'border-b-0', rowClassName)}
              data-state={row.getIsSelected() && 'selected'}
            >
              {row.getVisibleCells().map((cell) => (
                <TableCell key={cell.id} style={{ ...getCommonPinningStyles(cell.column) }}>
                  {flexRender(cell.column.columnDef.cell, cell.getContext())}
                </TableCell>
              ))}
            </TableRow>

            {/* Sub component */}
            {onRenderSubComponent && (
              <TableRow
                className={cn('hidden', {
                  'table-row': isExpanded
                })}
              >
                <TableCell colSpan={row.getVisibleCells().length}>{onRenderSubComponent(row)}</TableCell>
              </TableRow>
            )}
          </React.Fragment>
        )
      })}

      {onRenderAdditionalRow && (
        <TableRow>
          <TableCell colSpan={table.getAllFlatColumns().length}>{onRenderAdditionalRow(table)}</TableCell>
        </TableRow>
      )}
    </TableBody>
  )
}

export default DataTableBody

import type { Row, RowData, Table } from '@tanstack/react-table'
import { Checkbox, type CheckboxProps } from '@/registry/new-york/ui/checkbox/components/checkbox'

// Component
export const DataTableCheckboxCell = <TData extends RowData>({
  table,
  row,
  checkboxProps
}: {
  table: Table<TData>
  row: Row<TData>
  checkboxProps?: CheckboxProps
}) => {
  // Template
  return (
    <div className='flex h-full items-center justify-center'>
      <Checkbox
        checked={row.getIsSelected()}
        onCheckedChange={(value) => {
          row.toggleSelected(value as boolean)
          table?.options.meta?.setIsSelectAllRows?.(false)
        }}
        {...checkboxProps}
      />
    </div>
  )
}

import type { RowData, Table } from '@tanstack/react-table'
import { Checkbox, type CheckboxProps } from '@/registry/new-york/ui/checkbox/components/checkbox'

// Component
export const DataTableCheckboxHeader = <TData extends RowData>({
  table,
  checkboxProps
}: {
  table: Table<TData>
  checkboxProps?: CheckboxProps
}) => {
  // Template
  return (
    <div className='flex h-full w-full items-center justify-center'>
      <Checkbox
        checked={table.getIsAllPageRowsSelected() || (table.getIsSomePageRowsSelected() && 'indeterminate')}
        onCheckedChange={(value) => {
          table.toggleAllPageRowsSelected(!!value)
          table.options.meta?.setIsSelectAllRows?.(false)
        }}
        {...checkboxProps}
      />
    </div>
  )
}

import type { RowData, Table } from '@tanstack/react-table'
import { ChevronDownIcon } from 'lucide-react'
import { Button } from '@/registry/new-york/ui/button/components/button'
import { Checkbox } from '@/registry/new-york/ui/checkbox/components/checkbox'
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList
} from '@/registry/new-york/ui/command/components/command'
import { Popover, PopoverContent, PopoverTrigger } from '@/registry/new-york/ui/popover/components/popover'
import { cn } from '@/utils/ui'

// Component
export const DataTableColumnVisibilitySelection = <TData extends RowData>({ table }: { table: Table<TData> }) => {
  // Template
  return (
    <Popover>
      <PopoverTrigger asChild>
        <Button className={cn('font-normal [&_svg]:pointer-events-auto')} variant='outline'>
          <span>Columns</span>
          <ChevronDownIcon className='text-muted-foreground' />
        </Button>
      </PopoverTrigger>

      <PopoverContent className='min-w-(--radix-popover-trigger-width) p-0'>
        <Command>
          <div className='flex items-center gap-2 border-input border-b px-3'>
            <Checkbox
              checked={table.getIsAllColumnsVisible() || (table.getIsSomeColumnsVisible() && 'indeterminate')}
              onCheckedChange={(checked) => {
                table.toggleAllColumnsVisible(checked as boolean)
              }}
            />
            <div className='[&>div]:flex-1 [&>div]:border-b-0 [&>div]:border-b-none [&>div]:px-0'>
              <CommandInput placeholder='Search' />
            </div>
          </div>

          <CommandList className='scrollbar'>
            <CommandEmpty>No column found.</CommandEmpty>
            <CommandGroup>
              {table.getAllLeafColumns().map((column) => {
                if (typeof column.columnDef.header !== 'string' || !column.getCanHide()) {
                  return null
                }

                const isSelected = column.getIsVisible()
                const label = column.columnDef.header

                return (
                  <CommandItem key={column.id} onSelect={() => column.toggleVisibility(!isSelected)} value={label}>
                    <Checkbox checked={isSelected} />
                    <span>{label}</span>
                  </CommandItem>
                )
              })}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  )
}

import { flexRender, type RowData } from '@tanstack/react-table'
import { TableCell, TableFooter, TableRow } from '@/registry/new-york/ui/table/components/table'
import type { DataTableProps } from './data-table'

// Component
const DataTableFooter = <TData extends RowData>({
  table,
  className
}: Pick<DataTableProps<TData>, 'table'> & {
  className?: string
}) => {
  // Template
  return (
    <TableFooter className={className}>
      {/* Row */}
      {table.getFooterGroups().map((footerGroup) => (
        <TableRow key={footerGroup.id}>
          {footerGroup.headers.map((header) => (
            <TableCell colSpan={header.colSpan} key={header.id}>
              {header.isPlaceholder ? null : flexRender(header.column.columnDef.footer, header.getContext())}
            </TableCell>
          ))}
        </TableRow>
      ))}
    </TableFooter>
  )
}

export default DataTableFooter

import { flexRender, type RowData } from '@tanstack/react-table'
import { ChevronLeftIcon, ChevronRightIcon, PinOffIcon } from 'lucide-react'
import { Button } from '@/registry/new-york/ui/button/components/button'
import { TableHead, TableHeader, TableRow } from '@/registry/new-york/ui/table/components/table'
import { cn } from '@/utils/ui'
import type { DataTableProps } from './data-table'
import { getCommonPinningStyles } from './lib'

// Component
const DataTableHeader = <TData extends RowData>({
  table,
  className
}: Pick<DataTableProps<TData>, 'table'> & { className?: string }) => {
  // Template
  return (
    <TableHeader className={cn('sticky top-0 z-20 bg-background', className)}>
      {table.getHeaderGroups().map((headerGroup) => (
        <TableRow key={headerGroup.id}>
          {headerGroup.headers.map((header, headerIndex) => {
            const pinningPosition = header.column.getIsPinned()

            const columnRelativeDepth = header.depth - header.column.depth
            if (columnRelativeDepth > 1) {
              return null
            }

            let rowSpan = 1
            if (header.isPlaceholder) {
              const leafs = header.getLeafHeaders()
              const lastLeftDepth = leafs.at(-1)?.depth
              if (lastLeftDepth) {
                rowSpan = lastLeftDepth - header.depth
              }
            }

            return (
              <TableHead
                className={cn('space-y-1 border-b border-l', header.column.columnDef.meta?.className, {
                  'first:border-l-0': headerIndex === 0
                })}
                colSpan={header.colSpan}
                key={header.id}
                rowSpan={rowSpan}
                style={{
                  ...getCommonPinningStyles(header.column)
                }}
              >
                <div className='whitespace-nowrap'>
                  {flexRender(header.column.columnDef.header, header.getContext())}
                </div>

                {header.column.getCanPin() && (
                  <div className='flex gap-2'>
                    {pinningPosition !== 'left' && (
                      <Button
                        onClick={() => {
                          header.column.pin('left')
                        }}
                        size='icon-sm'
                        variant='outline'
                      >
                        <ChevronLeftIcon />
                      </Button>
                    )}

                    {pinningPosition && (
                      <Button
                        onClick={() => {
                          header.column.pin(false)
                        }}
                        size='icon-sm'
                        variant='outline'
                      >
                        <PinOffIcon />
                      </Button>
                    )}

                    {pinningPosition !== 'right' && (
                      <Button
                        onClick={() => {
                          header.column.pin('right')
                        }}
                        size='icon-sm'
                        variant='outline'
                      >
                        <ChevronRightIcon />
                      </Button>
                    )}
                  </div>
                )}
              </TableHead>
            )
          })}
        </TableRow>
      ))}
    </TableHeader>
  )
}

export default DataTableHeader

import type { RowData } from '@tanstack/react-table'
import debounce from 'lodash.debounce'
import type { NumberFormatValues } from 'react-number-format'
import { NumberInput } from '@/registry/new-york/molecules/number-input/components/number-input'
import { Pagination } from '@/registry/new-york/molecules/pagination/components/pagination'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue
} from '@/registry/new-york/ui/select/components/select'
import { cn } from '@/utils/ui'
import type { DataTableProps } from './data-table'

const pageSizeOptions = [10, 20, 30, 50, 100]

// Component
const DataTablePagination = <TData extends RowData>({
  table,
  className
}: Pick<DataTableProps<TData>, 'table'> & {
  className?: string
}) => {
  const pagination = table.getState().pagination
  const page = pagination.pageIndex + 1
  const pageSize = pagination.pageSize
  const pageCount = table.getPageCount()

  // Methods
  // Change number input value
  const changeNumberInputValue = debounce((values: NumberFormatValues) => {
    if (values.floatValue == null || values.floatValue < 1) {
      return
    }
    if (values.floatValue > pageCount) {
      return table.setPageIndex(pageCount - 1)
    }
    return table.setPageIndex(values.floatValue - 1)
  }, 400)

  // Template
  return (
    <div
      className={cn(
        'flex w-full flex-col items-center justify-between gap-4 border-t bg-muted/50 p-4 text-sm xl:flex-row',
        className
      )}
    >
      {/* Page input & page size */}
      <div className='flex flex-col items-center gap-4 xl:flex-row'>
        {/* Page input */}
        <div className='flex items-center gap-2'>
          <span>Move to page</span>
          <NumberInput
            className='w-14'
            defaultValue={page}
            isDisplayStepper={false}
            max={pageCount}
            min={1}
            onValueChange={changeNumberInputValue}
            placeholder=''
          />
        </div>

        {/* Page size selection */}
        <div className='flex items-center gap-2'>
          <span>Number of rows per page</span>
          <Select
            onValueChange={(value) => {
              table.setPageSize(Number(value))
            }}
            value={`${pageSize}`}
          >
            <SelectTrigger className='w-fit gap-1'>
              <SelectValue />
            </SelectTrigger>
            <SelectContent side='top'>
              {pageSizeOptions.map((pageSize) => (
                <SelectItem key={pageSize} value={`${pageSize}`}>
                  {pageSize}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
      </div>

      <Pagination
        isHasNextPage={table.getCanNextPage()}
        isHasPreviousPage={table.getCanPreviousPage()}
        onChangePage={(page) => table.setPageIndex(page - 1)}
        onGoToNextPage={table.nextPage}
        onGoToPreviousPage={table.previousPage}
        page={page}
        pageCount={pageCount}
      />
    </div>
  )
}

export default DataTablePagination

